import{_ as t,o,c as r,a2 as d}from"./chunks/framework.BaXgE4DV.js";const h=JSON.parse('{"title":"결정 기록","description":"","frontmatter":{},"headers":[],"relativePath":"decisions.md","filePath":"decisions.md","lastUpdated":1791554517000}'),a={name:"decisions.md"};function i(l,e,s,c,n,g){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="결정-기록" tabindex="-1">결정 기록 <a class="header-anchor" href="#결정-기록" aria-label="Permalink to &quot;결정 기록&quot;">​</a></h1><p>주요 설계 결정을 ADR(Architecture Decision Record) 형식으로 남깁니다. 새 결정은 아래에 번호를 이어 붙이고, 뒤집힌 결정은 지우지 말고 &quot;대체됨&quot;으로 표시합니다.</p><table tabindex="0"><thead><tr><th>#</th><th>결정</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td><a href="#adr-1">Gemini를 Cloud Functions로 이전</a></td><td>대체됨 (ADR-10)</td></tr><tr><td>2</td><td><a href="#adr-2">gratitudes get/list 규칙 분리</a></td><td>적용</td></tr><tr><td>3</td><td><a href="#adr-3">Circle 멤버십은 callable로 서버에서만 변경</a></td><td>적용 (1단계)</td></tr><tr><td>4</td><td><a href="#adr-4">Circle 삭제 시 감사 글 보존</a></td><td>적용</td></tr><tr><td>5</td><td><a href="#adr-5">feedMeta로 로딩 상태 구분</a></td><td>적용</td></tr><tr><td>6</td><td><a href="#adr-6">외부 공유는 작성자 opt-in</a></td><td>적용 (1단계)</td></tr><tr><td>7</td><td><a href="#adr-7">통계는 서버에서 KST 기준 계산</a></td><td>적용 (1단계)</td></tr><tr><td>8</td><td><a href="#adr-8">모바일 앱은 Capacitor</a></td><td>진행 중 (3단계)</td></tr><tr><td>9</td><td><a href="#adr-9">개발 문서는 비공개 저장소의 docs/ → 공개 Pages</a></td><td>적용</td></tr><tr><td>10</td><td><a href="#adr-10">AI 글쓰기 기능 제거, 질문으로 쓰기로 대체</a></td><td>적용 (2026-10-07 배포)</td></tr><tr><td>11</td><td><a href="#adr-11">질문은 사용자 제안 + 운영자 선정</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>12</td><td><a href="#adr-12">감사는 기본 개인 기록, Circle 공유는 선택</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>13</td><td><a href="#adr-13">화면을 막지 않는 시작과 기기 캐시</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>14</td><td><a href="#adr-14">신고·차단·자동 숨김</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>15</td><td><a href="#adr-15">계정 삭제 범위(삭제 vs 익명화)</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>16</td><td><a href="#adr-16">매일 알림: 웹 15분 단위, 앱 휴대폰 자체 알림</a></td><td>웹 적용 (2026-10-08 배포), 앱 코드 완료 (3단계, 배포 전)</td></tr><tr><td>17</td><td><a href="#adr-17">앱 로그인은 네이티브 시트 + JS SDK 세션 (<code>skipNativeAuth</code>)</a></td><td>코드 완료 (3단계, 배포 전)</td></tr></tbody></table><h2 id="adr-1" tabindex="-1">ADR-1 Gemini를 Cloud Functions로 이전 <a class="header-anchor" href="#adr-1" aria-label="Permalink to &quot;ADR-1 Gemini를 Cloud Functions로 이전 {#adr-1}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">대체됨</p><p>AI 글쓰기 기능을 없애면서 이 결정은 더 이상 적용되지 않습니다. → <a href="#adr-10">ADR-10</a></p></div><ul><li><strong>결정</strong>: Gemini API는 클라이언트가 아니라 callable 함수(<code>generateGratitude</code>)에서만 호출합니다. 키는 Secret Manager 비밀값 <code>GEMINI_API_KEY</code>로 둡니다.</li><li><strong>이유</strong>: 클라이언트 번들에 들어간 키는 누구나 꺼내 쓸 수 있습니다. 서버를 거치면 키를 숨기고, 사용자별 일일 한도(20회)·캐시·시간 제한으로 비용을 통제하고, 실패 시 fallback으로 UX를 지킬 수 있습니다. 질문은 서버의 질문 풀에서 골라 모델 호출 자체를 줄였습니다.</li><li><strong>대안</strong>: 클라이언트에서 직접 호출(키 노출), 클라이언트용 AI SDK + App Check(한도·캐시·프롬프트를 서버에서 통제하기 어려움).</li></ul><h2 id="adr-2" tabindex="-1">ADR-2 gratitudes get/list 규칙 분리 <a class="header-anchor" href="#adr-2" aria-label="Permalink to &quot;ADR-2 gratitudes get/list 규칙 분리 {#adr-2}&quot;">​</a></h2><ul><li><strong>결정</strong>: <code>gratitudes</code> 읽기 규칙을 <code>allow get</code>과 <code>allow list</code>로 나눕니다.</li><li><strong>이유</strong>: Firestore는 단건 읽기는 실제 문서로, 쿼리는 &quot;돌려줄 수 있는 모든 문서&quot;로 평가합니다. 하나의 <code>read</code> 규칙으로는 둘 다 정확히 표현하기 어렵습니다. 분리하면 get은 작성자·현재 멤버로 판단하고, list는 <code>userId ==</code> 또는 <code>groupId ==</code> 쿼리 형태만 허용해 교차 읽기를 최소화할 수 있습니다.</li><li><strong>대안</strong>: 단일 <code>read</code> 규칙(쿼리가 불필요하게 거부되거나 규칙이 느슨해짐), 다중 그룹 <code>in</code> 쿼리 허용(교차 읽기 10회 한도 초과 위험).</li></ul><h2 id="adr-3" tabindex="-1">ADR-3 Circle 멤버십은 callable로 서버에서만 변경 <a class="header-anchor" href="#adr-3" aria-label="Permalink to &quot;ADR-3 Circle 멤버십은 callable로 서버에서만 변경 {#adr-3}&quot;">​</a></h2><ul><li><strong>결정</strong>: <code>groups.memberIds</code>, <code>users.groupIds</code>, <code>inviteCodes</code>, <code>removedIds</code>는 Circle callable 7종(Admin SDK, 트랜잭션)만 바꿉니다. 클라이언트 쓰기는 규칙에서 거부합니다.</li><li><strong>이유</strong>: 참여 하나에도 초대 코드의 존재·만료·사용 횟수, Circle 정원, 사용자의 Circle 수, 내보낸 사용자 여부를 확인하고 세 문서를 원자적으로 바꿔야 합니다. 보안 규칙만으로는 이 검증과 원자성을 보장하기 어렵고, 규칙이 복잡해질수록 테스트·유지보수도 어렵습니다. 서버로 옮기면 한국어 오류 메시지도 일관되게 줄 수 있습니다.</li><li><strong>대안</strong>: 규칙에서 초대 코드를 교차 조회해 클라이언트가 직접 쓰기(원자성·정원·사용 횟수 검증이 어려움), <code>inviteCodes</code>에 관리자 ID 비정규화(동기화 부담).</li></ul><h2 id="adr-4" tabindex="-1">ADR-4 Circle 삭제 시 감사 글 보존 <a class="header-anchor" href="#adr-4" aria-label="Permalink to &quot;ADR-4 Circle 삭제 시 감사 글 보존 {#adr-4}&quot;">​</a></h2><ul><li><strong>결정</strong>: Circle을 삭제해도 그 Circle에 쓴 감사 글은 지우지 않습니다. 작성자는 계속 자기 글을 읽을 수 있습니다.</li><li><strong>이유</strong>: 감사 글은 Circle의 것이 아니라 작성자의 기록입니다. 관리자의 삭제로 다른 사람의 기록이 사라지면 안 됩니다. 규칙의 &quot;작성자는 항상 읽기 가능&quot; 분기가 이를 보장합니다.</li><li><strong>대안</strong>: 글까지 함께 삭제(작성자 기록 손실, 대량 삭제 비용), 글을 개인 글로 이동(<code>groupId</code> 일괄 수정 비용).</li></ul><h2 id="adr-5" tabindex="-1">ADR-5 feedMeta로 로딩 상태 구분 <a class="header-anchor" href="#adr-5" aria-label="Permalink to &quot;ADR-5 feedMeta로 로딩 상태 구분 {#adr-5}&quot;">​</a></h2><ul><li><strong>결정</strong>: 피드 상태(현재 <code>groupStore.feeds[key]</code>, 처음에는 <code>feedMeta[groupId]</code>)가 없으면(undefined) 로딩 중, 있으면 데이터 수신 완료로 봅니다.</li><li><strong>이유</strong>: 빈 배열 하나로는 &quot;아직 안 옴&quot;과 &quot;글이 없음&quot;을 구분할 수 없어, 피드가 잠깐 빈 화면으로 보였다가 채워지는 문제가 생깁니다. 구독 오류(권한 상실 등) 때는 <code>error</code>를 표시한 상태를 넣어 로딩이 끝나되 &quot;글이 없음&quot;으로 보이지 않게 합니다. 내 기록이 기본 탭이 된 뒤로는 오류를 빈 피드로 보이면 &quot;기록이 사라졌다&quot;로 읽히기 때문입니다.</li><li><strong>대안</strong>: 별도 <code>loading</code> 플래그를 Circle마다 관리(상태가 늘어나고 어긋나기 쉬움).</li></ul><h2 id="adr-6" tabindex="-1">ADR-6 외부 공유는 작성자 opt-in <a class="header-anchor" href="#adr-6" aria-label="Permalink to &quot;ADR-6 외부 공유는 작성자 opt-in {#adr-6}&quot;">​</a></h2><ul><li><strong>결정</strong>: 공유 링크는 작성자가 공개한 것만 보여 줍니다. 감사 글은 <code>isPublic</code>, 캘린더 월·배지는 <code>publicShares/{uid}</code>에 등록된 것만. 공개하지 않은 것은 내용 없이 &quot;비공개&quot; 안내(<code>noindex</code>)를 돌려줍니다.</li><li><strong>이유</strong>: 감사 글은 Circle 안에서 나누려고 쓴 개인적인 기록입니다. 링크가 다른 곳으로 퍼지더라도 작성자가 명시적으로 고른 것만 밖에 보여야 합니다. 공개를 취소하면 1분 안에 반영되도록 공유 페이지 캐시를 짧게 둡니다.</li><li><strong>대안</strong>: 기본 공개 + 비공개 전환(작성자가 모르는 사이 노출), 공유마다 별도 토큰 URL 발급(구현·관리 복잡도).</li></ul><h2 id="adr-7" tabindex="-1">ADR-7 통계는 서버에서 KST 기준 계산 <a class="header-anchor" href="#adr-7" aria-label="Permalink to &quot;ADR-7 통계는 서버에서 KST 기준 계산 {#adr-7}&quot;">​</a></h2><ul><li><strong>결정</strong>: <code>userStats</code>(연속일, 월별 수)는 <code>onGratitudeCreated</code> 트리거가 KST 날짜로 계산하고, 클라이언트는 읽기만 합니다. 표시용 판단(연속일이 살아 있는지)도 같은 KST 규칙을 씁니다.</li><li><strong>이유</strong>: 클라이언트가 쓰면 값을 조작할 수 있고, 기기 시간대마다 &quot;오늘&quot;이 달라 연속일이 어긋납니다. 사용자 대부분이 한국에 있으므로 KST를 단일 기준으로 삼았습니다. 트리거는 마커로 멱등하게 만들어 중복 집계를 막습니다.</li><li><strong>대안</strong>: 클라이언트 계산(조작·시간대 불일치), 사용자별 시간대 저장(복잡도 대비 이득이 작음), 매번 글 목록으로 다시 계산(읽기 비용).</li></ul><h2 id="adr-8" tabindex="-1">ADR-8 모바일 앱은 Capacitor <a class="header-anchor" href="#adr-8" aria-label="Permalink to &quot;ADR-8 모바일 앱은 Capacitor {#adr-8}&quot;">​</a></h2><ul><li><strong>결정</strong>: iOS·Android 앱은 Capacitor로 기존 React 앱을 감싸 만듭니다. 로그인·푸시·딥링크·공유는 네이티브 플러그인으로 처리합니다.</li><li><strong>이유</strong>: 한 사람이 웹과 두 앱을 함께 유지해야 하므로 코드 재사용이 가장 중요합니다. Capacitor는 지금의 React·Firebase JS SDK 코드를 거의 그대로 쓰면서 스토어 출시에 필요한 네이티브 기능을 붙일 수 있습니다.</li><li><strong>대안</strong>: React Native 재작성(UI 전면 재작성), 네이티브 Swift·Kotlin(유지 인력 부족), PWA만 유지(App Store 배포 불가, iOS 푸시 제약), Android TWA(iOS 해결 안 됨).</li><li><strong>세부 내용</strong>: <a href="/grato-docs/mobile/">iOS·Android 앱</a>. 앱 ID <code>cc.mknw.grato</code>, Capacitor 8.5, iOS는 Swift Package Manager. 로그인 방식은 <a href="#adr-17">ADR-17</a></li></ul><h2 id="adr-9" tabindex="-1">ADR-9 개발 문서는 비공개 저장소의 docs/ → 공개 Pages <a class="header-anchor" href="#adr-9" aria-label="Permalink to &quot;ADR-9 개발 문서는 비공개 저장소의 docs/ → 공개 Pages {#adr-9}&quot;">​</a></h2><ul><li><strong>결정</strong>: 문서는 비공개 소스 저장소의 <code>docs/</code>(VitePress)에 코드와 함께 두고, <code>main</code>에 반영되면 GitHub Actions가 빌드해 공개 저장소 <code>subongjeong/grato-docs</code>의 GitHub Pages로 배포합니다.</li><li><strong>이유</strong>: 문서가 코드 옆에 있어야 같은 커밋에서 함께 고칠 수 있습니다. 소스는 비공개로 두면서 빌드 결과만 공개하면 무료 Pages를 쓰고 외부 협업자·AI 에이전트도 문서를 볼 수 있습니다. 배포 키는 공개 저장소에만 쓰기 권한이 있고, 공개 저장소의 커밋 메시지는 고정 문구로 둡니다.</li><li><strong>대안</strong>: 소스 저장소 자체를 공개(코드·이력 노출), 비공개 저장소 Pages(유료 플랜·접근 제어 필요), 별도 위키·노션(코드와 따로 놀아 갱신 누락).</li><li><strong>주의</strong>: 문서가 공개이므로 비밀값, 관리자 정보, 프로덕션에 반영되지 않은 보안 문제의 세부 내용은 쓰지 않습니다. → <a href="/grato-docs/contributing-docs">문서 작성 규칙</a></li></ul><h2 id="adr-10" tabindex="-1">ADR-10 AI 글쓰기 기능 제거, 질문으로 쓰기로 대체 <a class="header-anchor" href="#adr-10" aria-label="Permalink to &quot;ADR-10 AI 글쓰기 기능 제거, 질문으로 쓰기로 대체 {#adr-10}&quot;">​</a></h2><ul><li><strong>결정</strong>: Gemini로 초안을 만들던 AI 질문 모드를 없애고, 기기 안의 질문 풀로 동작하는 &quot;질문으로 쓰기&quot;로 바꿉니다. 만 14세 이상이 쓰는 서비스로서, 사용자가 쓴 글은 외부 AI 서비스로 보내지 않습니다. <ul><li>질문은 <code>src/content/questions.js</code>의 풀에서 클라이언트가 무작위로 고르고, 답변 1~2개를 빈 줄로 이어 붙여 초안을 만듭니다. 제목은 사용자가 씁니다. → <a href="/grato-docs/features/guided-writing">질문으로 쓰기</a></li><li>이후 질문의 출처는 운영자가 선정한 질문으로 바뀌었습니다(앱 안의 목록은 대체용). 답변과 초안을 기기 안에서 만드는 것은 그대로입니다. → <a href="#adr-11">ADR-11</a></li><li>함수 <code>generateQuestion</code>, <code>generateGratitude</code>와 비밀값 <code>GEMINI_API_KEY</code>, 파라미터 <code>GEMINI_MODEL</code>을 없앱니다.</li><li>컬렉션 <code>aiSessions</code>, <code>aiUsage</code>, <code>aiCache</code>는 규칙에서 클라이언트 접근을 모두 막고(기본 거부), 남은 문서는 <code>purgeAiData</code> 스크립트로 지웁니다. 목적이 끝난 데이터를 보관하지 않기 위해서입니다.</li><li>화면 문구에는 &quot;AI&quot;, &quot;인공지능&quot;을 쓰지 않습니다.</li></ul></li><li><strong>이유</strong>: 외부 생성형 AI로 사용자 글을 보내려면 서비스 대상 연령과 맞는 이용 조건, 별도의 동의와 고지·표시 절차가 따릅니다. 감사 일기는 개인적인 기록이라 이 부담에 비해 얻는 것이 작습니다. 사용자에게 가장 도움이 되던 부분은 &quot;무엇을 쓸지 떠올리게 하는 질문&quot;이었고, 질문은 이미 고정된 풀에서 나오고 있었으므로 모델 없이도 그 가치를 지킬 수 있습니다. 함수 호출·비용·장애 지점도 함께 사라집니다.</li><li><strong>대안</strong>: 동의 화면과 표시를 추가하고 유지(연령 조건과 맞지 않고 출시 절차가 복잡해짐), 다른 AI 제공자로 교체(같은 동의·고지 부담), 기기 내 모델(앱 크기·성능 대비 이득이 작음).</li></ul><h2 id="adr-11" tabindex="-1">ADR-11 질문은 사용자 제안 + 운영자 선정 <a class="header-anchor" href="#adr-11" aria-label="Permalink to &quot;ADR-11 질문은 사용자 제안 + 운영자 선정 {#adr-11}&quot;">​</a></h2><ul><li><strong>결정</strong>: 질문으로 쓰기의 질문은 운영자가 선정한 질문(<code>questions</code>, <code>status == &quot;approved&quot;</code>)에서 고릅니다. 기본 질문은 <code>src/content/questions.json</code>이 원본이고 <code>seedQuestions</code> 스크립트가 Firestore에 넣습니다. 사용자는 질문을 제안할 수 있고(<code>submitQuestion</code>), 운영자(<code>users.isAdmin</code>)만 선정·반려·숨김을 합니다(<code>reviewQuestion</code>). 선정된 사용자 질문에는 제안자의 공개 이름이 함께 보이고, 제안자는 처음 선정될 때 알림을, 선정 수에 따라 배지(1·3·10번)를 받습니다. → <a href="/grato-docs/features/questions">질문 제안과 선정</a></li><li><strong>안전장치</strong>: <ul><li>모든 쓰기는 서버 함수만 합니다(운영자도 클라이언트에서 직접 쓰지 않음).</li><li>제출 때 내용 필터(욕설·혐오 표현, URL, 이메일, 전화번호)와 한도(하루 5개, 하루 시도 30번, 검토 중 20개, 전체 대기 300개), 중복 확인을 적용합니다.</li><li><strong>사전 검토</strong>: 제안한 질문은 운영자가 선정하기 전까지 제안자 본인과 운영자만 봅니다.</li><li>선정된 질문 문서는 로그인한 누구나 읽으므로 공개되면 안 되는 값(운영자 신원, 고치기 전 원문)은 다른 컬렉션에 둡니다.</li><li>선정 때 제안자의 공개 이름이 운영자가 본 이름과 다르면 선정하지 않습니다. 운영자가 확인하지 않은 이름이 질문과 함께 공개되지 않게 하기 위해서입니다.</li></ul></li><li><strong>이유</strong>: 좋은 질문은 사용자에게서 나오고, 자기 질문이 쓰이는 경험은 참여 동기가 됩니다. 하지만 질문은 모든 사용자에게 보이므로 공개 전에 사람이 확인해야 합니다. 질문을 앱 안의 목록에만 두면 앱을 배포해야만 바꿀 수 있어, Firestore로 옮기고 앱 안의 목록은 읽지 못할 때의 대체용으로 남겼습니다.</li><li><strong>대안</strong>: 자동 공개 + 신고(부적절한 질문이 먼저 노출됨), 생성형 모델로 질문 만들기(<a href="#adr-10">ADR-10</a>에서 제외), 앱 안의 목록만 유지(사용자 참여 불가, 수정에 배포 필요).</li></ul><h2 id="adr-12" tabindex="-1">ADR-12 감사는 기본 개인 기록, Circle 공유는 선택 <a class="header-anchor" href="#adr-12" aria-label="Permalink to &quot;ADR-12 감사는 기본 개인 기록, Circle 공유는 선택 {#adr-12}&quot;">​</a></h2><ul><li><strong>결정</strong>: 새 감사 글의 기본 공개 범위는 &quot;나만 보기&quot;(<code>groupId: null</code>)입니다. Circle 공유는 작성 화면에서 &quot;Circle에 공유&quot;와 Circle을 직접 고를 때만 되고, Circle을 미리 선택해 두지 않습니다. 홈 피드의 첫 탭이자 기본 탭은 &quot;내 기록&quot;이고, Circle이 없어도 있습니다. Circle은 계속 비공개이고(목록·검색 없음) 초대 코드로만 참여합니다. → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a></li><li><strong>이유</strong>: 감사 일기는 먼저 자신을 위한 기록입니다. 예전처럼 Circle이 미리 선택되어 있으면 사용자가 의도하지 않게 개인적인 글을 다른 사람에게 보일 수 있습니다. 나누는 것은 분명한 선택이어야 합니다. Circle이 없는 사용자도 홈에서 바로 자기 기록을 볼 수 있어야 합니다.</li><li><strong>영향</strong>: 글을 Circle에 공유해야만 받던 &quot;함께하기&quot;(<code>circle_count</code>) 배지는 이제 Circle을 만들거나 참여할 때 평가합니다.</li><li><strong>대안</strong>: 마지막으로 고른 Circle 기억(같은 실수가 반복됨), 작성 후 공유 전환(글 내용과 <code>groupId</code>를 고칠 수 없는 구조라 변경 규칙이 새로 필요).</li></ul><h2 id="adr-13" tabindex="-1">ADR-13 화면을 막지 않는 시작과 기기 캐시 <a class="header-anchor" href="#adr-13" aria-label="Permalink to &quot;ADR-13 화면을 막지 않는 시작과 기기 캐시 {#adr-13}&quot;">​</a></h2><ul><li><strong>결정</strong>: 앱은 Firebase Auth가 사용자를 알려 주는 즉시 화면을 그립니다. 사용자 프로필은 <code>users/{uid}</code> 실시간 구독으로 받고, 로그인 동기화(이름·태그·사진 정리)는 화면이 뜬 뒤 뒤에서 실행합니다(바뀐 것이 없으면 쓰기 없음). Firestore는 기기 캐시(IndexedDB)를 켜고, 로그아웃 때 이 기기의 캐시를 지웁니다. 페이지는 경로별로 코드를 나누고, Functions·Storage·Messaging 모듈은 처음 쓸 때 받습니다. → <a href="/grato-docs/architecture/client#performance">성능</a></li><li><strong>이유</strong>: 측정해 보니 시작할 때마다 서버 왕복 6~7번(쓰기 포함)을 차례로 기다린 뒤에야 첫 화면이 나왔고, 다시 열어도 캐시가 없어 모두 새로 받았습니다. 느린 휴대폰 조건에서 재방문 첫 화면이 1.6초 → 0.45초로 줄었습니다.</li><li><strong>영향</strong>: 페이지는 프로필을 &quot;아직 모름(<code>undefined</code>)&quot;과 &quot;없음(<code>null</code>)&quot;으로 구분하고, 모르는 동안 뼈대(스켈레톤)를 보여 줍니다. 새 사용자의 첫 글·댓글은 로그인 동기화가 끝날 때까지 기다립니다. 공용 기기 보호를 위해 로그아웃은 캐시를 지운 뒤 페이지를 다시 불러옵니다. 배포로 이전 버전 코드 파일이 사라지면 열려 있던 탭은 한 번 자동으로 새로고침합니다.</li><li><strong>대안</strong>: 동기화를 그대로 두고 로딩 화면만 다듬기(실제 대기 시간은 그대로), 서비스 워커로 앱 전체 캐시(업데이트·무효화 관리 부담이 커서 앱 포팅 때 다시 검토).</li></ul><h2 id="adr-14" tabindex="-1">ADR-14 신고·차단·자동 숨김 <a class="header-anchor" href="#adr-14" aria-label="Permalink to &quot;ADR-14 신고·차단·자동 숨김 {#adr-14}&quot;">​</a></h2><ul><li><strong>결정</strong>: 다른 사람에게 보이는 콘텐츠(Circle 글, 링크 공개 글, 댓글, 공개 이름, Circle 이름)에 네 가지 수단을 둡니다. → <a href="/grato-docs/features/safety">신고·차단과 자동 숨김</a><ul><li><strong>신고</strong>: 사용자가 <code>reports</code>에 직접 만들고(자동 ID, 규칙이 형태 검사), 운영자만 읽습니다. 도배 판단과 대상 정보 복사, 운영자 푸시는 <code>onReportCreated</code>가 합니다.</li><li><strong>차단</strong>: <code>users/{uid}/blocks</code>에 본인이 씁니다. 화면에서 거르는 것은 클라이언트, 알림에서 빼는 것은 서버가 하고, 운영자에게는 낮은 우선순위 신고로 알립니다. 상대에게는 알리지 않습니다.</li><li><strong>자동 숨김(사후 검사 + 즉시 숨김)</strong>: 저장은 막지 않고, 트리거가 욕설·혐오 표현을 찾으면 바로 숨긴 뒤 운영자 대기열에 올립니다. 숨김은 서버만 쓰는 <code>moderation</code> 필드이고, 작성자에게는 &quot;검토 중이에요&quot;로 보입니다. 숨긴 Circle 글은 <code>groupId</code>를 <code>moderation.groupId</code>로 옮겨 Circle 피드 쿼리에서 빠집니다.</li><li><strong>운영자 처리</strong>: <code>moderate</code> callable 하나로 숨기기·해제·삭제·이용 정지·문제 없음을 하고, 같은 대상의 열린 신고를 한꺼번에 닫으며, 작업을 <code>adminAuditLogs</code>에 남깁니다.</li><li>&quot;나만 보기&quot; 글은 대상이 아닙니다. 신고도 검사도 하지 않고, 운영자도 읽을 수 없습니다.</li></ul></li><li><strong>이유</strong>: 스토어는 UGC 앱에 신고·차단·필터와 빠른 대응(약관의 24시간 처리 약속)을 요구합니다. 감사 글은 친구끼리 나누는 짧은 글이라, 저장 전에 막으면 정상 문장이 막히는 불편이 크고(띄어쓰기·합성어 오탐) 우회도 쉽습니다. 저장은 받아 두고 서버가 즉시 숨기면 다른 사람에게 노출되는 시간은 거의 없으면서 작성자의 기록은 사라지지 않습니다. 연락처·링크는 친구에게 쓰는 글에서 자연스러워 자동으로 숨기지 않고 신고에 맡깁니다(질문 제안과 다른 기준). Firestore 쿼리는 &quot;숨김이 아닌 것&quot;을 조건으로 걸 수 없어(필드 없는 예전 문서가 빠짐), 숨긴 글을 Circle 피드에서 빼려면 <code>groupId</code> 자체를 옮겨야 했습니다. 개인 일기는 운영자에게도 보이지 않아야 한다는 원칙(<a href="#adr-12">ADR-12</a>)을 신고 처리에서도 지킵니다.</li><li><strong>대안</strong>: 저장 전에 클라이언트·규칙에서 거절(오탐 불편, 규칙에 단어 목록을 둘 수 없음), 사전 검토(친구 사이의 즉시성을 잃음 — 질문 제안에만 적용, <a href="#adr-11">ADR-11</a>), 숨김을 클라이언트 필터로만 처리(Circle 피드 쿼리에 계속 나옴), 외부 모더레이션 API(사용자 글을 외부로 보내지 않는다는 <a href="#adr-10">ADR-10</a>과 충돌), 차단을 서버 쿼리에 반영(Circle마다 쿼리 조건이 늘고 교차 읽기 한도에 걸림).</li></ul><h2 id="adr-15" tabindex="-1">ADR-15 계정 삭제 범위(삭제 vs 익명화) <a class="header-anchor" href="#adr-15" aria-label="Permalink to &quot;ADR-15 계정 삭제 범위(삭제 vs 익명화) {#adr-15}&quot;">​</a></h2><ul><li><strong>결정</strong>: 계정 삭제(<code>deleteAccount</code>)는 <strong>&quot;내 것은 지우고, 다른 사람에게 이미 의미가 생긴 것은 나와의 연결만 끊는다&quot;</strong> 를 따릅니다. → <a href="/grato-docs/features/account#deletion-scope">계정 삭제</a><ul><li><strong>삭제</strong>: 계정, 프로필, 이름 선점, 내 감사 글과 그 글의 모든 댓글(다른 사람이 쓴 것 포함), 다른 글에 남긴 내 댓글과 리액션, 통계·배지·공유 설정, 푸시 토큰, 의견, 차단 목록, 선정되지 않은 질문 제안과 모든 제안의 원문, 프로필 사진.</li><li><strong>Circle</strong>: 모두 나가고, 관리자였다면 가장 오래 함께한 멤버에게 넘깁니다. 혼자 있던 Circle만 지웁니다. Circle에 쓴 다른 사람의 글은 그대로입니다(<a href="#adr-4">ADR-4</a>).</li><li><strong>익명화</strong>: 선정된 제안 질문(다른 사람이 쓰는 중), 이용 통계 이벤트, 신고 기록(보낸 신고·받은 신고, 처리 후 1년 보관), 운영자 조치 기록.</li><li>삭제 직후 남은 로그인 토큰으로 데이터가 되살아나지 않게 서버 전용 잠금 문서(<code>disabledUsers</code>, 약 2시간)를 먼저 쓰고, Auth 사용자는 마지막에 지웁니다. 최근 10분 안에 로그인한 경우에만 삭제합니다.</li></ul></li><li><strong>이유</strong>: 스토어(Apple 5.1.1(v), Google Play)와 개인정보 보호법은 계정과 개인 데이터의 삭제를 요구하고, 목적을 다한 정보는 지체 없이 파기해야 합니다. 그래서 기본값은 삭제입니다. 다만 선정된 질문은 다른 사용자가 글을 쓰는 데 쓰고 있어, 지우면 남의 기록 흐름이 끊기므로 작성자 정보만 지웁니다. 신고 기록은 재발 방지와 분쟁 대응을 위해 처리방침에 적은 기간만 남기되 누구인지는 지웁니다. Circle을 함께 지우면 다른 멤버의 공간이 사라지므로 넘겨줍니다. 내 글에 달린 남의 댓글은 글이 없으면 맥락이 없고 그 글의 일부로 보아 함께 지웁니다.</li><li><strong>대안</strong>: 모두 삭제(선정된 질문이 사라져 다른 사용자에게 영향, 다른 사람이 보낸 신고의 처리 기록까지 사라져 분쟁 대응과 처리방침의 보관 약속에 맞지 않음), 모두 익명화(글과 댓글은 개인적인 내용이라 익명화로는 개인정보가 남음), 유예 기간 후 삭제(복구 요청 대응은 쉬우나 즉시 삭제 요구와 맞지 않고 예약 작업이 필요 — 출시 후 다시 검토), 삭제를 운영자가 처리(스토어가 앱 안 삭제를 요구).</li></ul><h2 id="adr-16" tabindex="-1">ADR-16 매일 알림: 웹은 15분 단위 서버 푸시, 앱은 휴대폰 자체 알림 <a class="header-anchor" href="#adr-16" aria-label="Permalink to &quot;ADR-16 매일 알림: 웹은 15분 단위 서버 푸시, 앱은 휴대폰 자체 알림 {#adr-16}&quot;">​</a></h2><ul><li><strong>결정</strong>: 웹의 매일 알림은 서버가 15분마다(<code>*/15 * * * *</code>, KST) 그 시각을 고른 사용자에게 푸시를 보내고, 설정 화면도 15분 단위로 고릅니다. iOS·Android 앱에서는 서버 푸시 대신 **휴대폰 자체 알림(로컬 알림)**으로 사용자가 고른 시각에 정확히 띄웁니다(3단계에서 구현). 앱이 로컬 알림을 켠 사용자는 서버 발송 대상에서 빼서 알림이 두 번 가지 않게 합니다.</li><li><strong>이유</strong>: 사용자가 고른 시각에 정확히 오는 것이 핵심입니다. 서버 스케줄러는 실행 간격만큼 오차가 생기고, 예전 설정(<code>every 1 hours</code>)은 매시 40분에 돌아 20시 알림이 20시 40분에 왔습니다. 휴대폰 자체 알림은 분 단위로 정확하고 인터넷 연결이 없어도 옵니다.</li><li><strong>대안</strong>: 서버를 1분마다 실행(호출 수 증가 대비 이점이 작음), 시 단위 유지(사용자 요구와 맞지 않음).</li><li><strong>앱 구현 (3단계)</strong>: 시각은 웹과 같은 15분 단위 설정을 그대로 씁니다. 앞으로 14일 치를 하루씩 예약해 글을 쓴 날은 뺍니다. 예약하는 동안 <code>notificationSettings.dailyReminderChannel = &#39;local&#39;</code>과 <code>dailyReminderLocalAt</code>을 쓰고, 서버는 이 표시가 14일 안이면 그 사용자를 건너뜁니다(웹 브라우저에도 보내지 않아 하루 한 번). 앱을 지워 표시를 되돌리지 못해도 14일 뒤 서버 알림이 다시 갑니다. Android는 정확한 알람 권한을 요청하지 않아(설정 화면으로 보내야 하고 심사 대상) 절전 중에는 몇 분 늦을 수 있습니다. → <a href="/grato-docs/features/notifications#local-reminder">알림: 앱</a></li></ul><h2 id="adr-17" tabindex="-1">ADR-17 앱 로그인은 네이티브 시트 + JS SDK 세션 (<code>skipNativeAuth</code>) <a class="header-anchor" href="#adr-17" aria-label="Permalink to &quot;ADR-17 앱 로그인은 네이티브 시트 + JS SDK 세션 (`skipNativeAuth`) {#adr-17}&quot;">​</a></h2><ul><li><strong>결정</strong>: iOS·Android 앱의 Google·Apple 로그인은 <code>@capacitor-firebase/authentication</code>으로 <strong>플랫폼의 로그인 화면만</strong> 띄우고(<code>skipNativeAuth: true</code>), 받은 ID 토큰으로 웹과 같은 <strong>Firebase JS SDK</strong>에서 <code>signInWithCredential</code>을 합니다. 세션은 JS SDK 하나에만 두고, Firestore·Functions·Storage·규칙은 웹 코드를 그대로 씁니다. 계정 삭제의 재인증도 같은 시트 → <code>reauthenticateWithCredential</code>입니다. → <a href="/grato-docs/mobile/#sign-in">iOS·Android 앱: 로그인</a><ul><li>플러그인은 패키지의 JS 진입점 대신 <code>registerPlugin</code>으로 등록하고, 앱에서만 동적으로 불러옵니다(진입점의 웹 구현이 <code>firebase/auth</code>를 웹사이트 시작 코드에 끌어들임).</li><li>Apple 연결 해제는 iOS에서 네이티브 로그인의 인증 코드를, Android에서 액세스 토큰을 씁니다. JS SDK의 <code>revokeAccessToken</code>은 액세스 토큰만 보내므로 iOS 인증 코드는 Identity Toolkit <code>accounts:revokeToken</code>을 직접 부릅니다.</li><li>로그아웃할 때 네이티브 SDK도 로그아웃합니다(기억된 Google 계정, Android Apple 로그인이 남기는 네이티브 세션).</li></ul></li><li><strong>이유</strong>: Google은 앱 안 웹뷰의 OAuth를 막고(<code>disallowed_useragent</code>), 팝업·리디렉트는 앱의 출처(<code>capacitor://localhost</code>)에서 동작하지 않습니다. 세션을 JS SDK 한 곳에 두면 웹과 같은 uid로 로그인되고, 토큰 갱신·기기 캐시·로그아웃·계정 삭제 흐름과 보안 규칙을 하나도 바꾸지 않아도 됩니다. 한 사람이 웹과 두 앱을 유지하므로 인증 경로가 하나인 것이 가장 중요합니다.</li><li><strong>대안</strong>: 네이티브 Firebase SDK에 로그인하고 JS SDK와 세션을 맞추기(세션이 두 개라 만료·로그아웃·계정 전환이 어긋날 수 있음), 앱 안 브라우저(Safari View Controller·Custom Tabs)로 웹 OAuth 후 커스텀 스킴으로 돌아오기(흐름이 길고 Apple 로그인은 시스템 시트가 기대됨), Google 전용 커뮤니티 플러그인 + Apple 별도 플러그인(플러그인 두 개, 오류 처리 두 벌), Firestore 등까지 네이티브 SDK로 옮기기(웹과 코드가 갈라짐).</li><li><strong>조건</strong>: Firebase에 iOS·Android 앱(<code>cc.mknw.grato</code>)이 등록되어 있어야 하고, Android는 서명 키의 SHA-1·SHA-256을 등록해야 합니다(출시 키는 출시 때). Android의 Apple 로그인은 Firebase Android SDK의 웹 흐름을 쓰므로 Apple Services ID에 Firebase 기본 인증 도메인의 Return URL이 필요합니다.</li></ul><h2 id="adr-18" tabindex="-1">ADR-18 홈 화면 위젯은 숫자·날짜·질문만, 앱이 쓴 요약본으로 <a class="header-anchor" href="#adr-18" aria-label="Permalink to &quot;ADR-18 홈 화면 위젯은 숫자·날짜·질문만, 앱이 쓴 요약본으로 {#adr-18}&quot;">​</a></h2><ul><li><strong>결정</strong>: iOS·Android 홈 화면 위젯(iOS는 잠금 화면 포함)은 연속일, 오늘 기록 여부, 이번 주 기록, 오늘의 질문만 보여 줍니다. 감사 글 내용·이름·Circle은 넣지 않습니다. 앱이 KST 날짜와 숫자로 된 작은 요약본을 위젯 저장소(iOS App Group, Android SharedPreferences)에 쓰고, 위젯은 서버에 접속하지 않고 같은 표시 규칙으로 날짜가 바뀌는 것을 스스로 처리합니다. → <a href="/grato-docs/mobile/#widgets">iOS·Android 앱: 위젯</a></li><li><strong>이유</strong>: 위젯은 휴대폰을 보는 누구에게나 보이고, 감사 글은 기본이 &quot;나만 보기&quot;입니다. 기록 습관을 돕는 데는 숫자와 질문이면 충분합니다. 위젯이 직접 Firestore에 접속하면 인증·규칙·토큰 갱신을 네이티브에서 따로 맞춰야 하고, 요약본 방식이면 오프라인에서도 바로 그려집니다.</li><li><strong>대안</strong>: 지난 감사 글 다시 보기(내용 노출 위험, 필요하면 앱 설정으로 켜는 선택 기능으로 따로 검토), 위젯에서 Firestore 직접 읽기(인증 경로가 하나 더 생김), 서버가 위젯 데이터를 푸시(푸시 권한이 필요하고 늦음).</li></ul><h2 id="adr-19" tabindex="-1">ADR-19 환경 분리: 지금은 로컬 에뮬레이터 + 운영, 출시 뒤 스테이징 <a class="header-anchor" href="#adr-19" aria-label="Permalink to &quot;ADR-19 환경 분리: 지금은 로컬 에뮬레이터 + 운영, 출시 뒤 스테이징 {#adr-19}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 개발과 QA는 기본으로 <strong>로컬 Firebase 에뮬레이터</strong>(가짜 프로젝트 <code>demo-grato</code>)에서 합니다(<code>npm run dev</code>). 실제 프로젝트에 붙는 개발 서버는 <code>npm run dev:prod</code>로 이름을 나눴습니다. 스토어 출시 뒤에는 <strong>스테이징 프로젝트</strong>(<code>grato-stg</code>, <code>stg.grato.today</code>)와 스테이징 앱 빌드(<code>cc.mknw.grato.stg</code>, &quot;Grato β&quot;), GitHub Actions 자동 배포(main 병합 → 스테이징, 승인 → 운영)를 더합니다. → <a href="/grato-docs/guide/getting-started">시작하기: 개발 서버</a></li><li><strong>이유</strong>: Firebase 프로젝트가 운영 하나뿐이라 개발 서버·QA·배포가 모두 실사용자 데이터에 닿았습니다. 1인 운영에서 클라우드 dev·stg·prod 세 벌은 관리 부담이 커서, dev는 에뮬레이터로 대신하고 stg 하나만 둡니다. 운영 데이터는 스테이징으로 복사하지 않습니다(개인정보).</li><li><strong>대안</strong>: 클라우드 dev 프로젝트(설정·비용·로그인 설정이 한 벌 더), 한 프로젝트 안에서 컬렉션 접두어로 나누기(규칙·트리거·인덱스가 섞여 사고 위험).</li></ul>',42)])])}const A=t(a,[["render",i]]);export{h as __pageData,A as default};
